/** A Timestamp represents a point in time independent of any time zone or local calendar, encoded as a count of seconds and fractions of seconds at nanosecond resolution. The count is relative to an epoc… */
export interface Timestamp {
    /** Represents seconds of UTC time since Unix epoch 1970-01-01T00:00:00Z. Must be between -62135596800 and 253402300799 inclusive (which corresponds to 0001-01-01T00:00:00Z to 9999-12-31T23:59:59Z). */
    seconds: string;
    /** Non-negative fractions of a second at nanosecond resolution. This field is the nanosecond portion of the duration, not an alternative to seconds. Negative second values with fractions must still have… */
    nanos: number;
}

/** `Any` contains an arbitrary serialized protocol buffer message along with a URL that describes the type of the serialized message. In its binary encoding, an `Any` is an ordinary message; but in other… */
export interface Any {
    /** Identifies the type of the serialized Protobuf message with a URI reference consisting of a prefix ending in a slash and the fully-qualified type name. Example: type.googleapis.com/google.protobuf.Str… */
    typeUrl: string;
    /** Holds a Protobuf serialization of the type described by type_url. */
    value: Uint8Array;
}

/** A Duration represents a signed, fixed-length span of time represented as a count of seconds and fractions of seconds at nanosecond resolution. It is independent of any calendar and concepts like "day"… */
export interface Duration {
    /** Signed seconds of the span of time. Must be from -315,576,000,000 to +315,576,000,000 inclusive. Note: these bounds are computed from: 60 sec/min * 60 min/hr * 24 hr/day * 365.25 days/year * 10000 yea… */
    seconds: string;
    /** Signed fractions of a second at nanosecond resolution of the span of time. Durations less than one second are represented with a 0 `seconds` field and a positive or negative `nanos` field. For duratio… */
    nanos: number;
}

/** `FieldMask` represents a set of symbolic field paths, for example: paths: "f.a" paths: "f.b.d" Here `f` represents a field in some root message, `a` and `b` fields in the message found in `f`, and `d`… */
export interface FieldMask {
    /** The set of field mask paths. */
    paths: string[];
}

/** Represents a JSON object. An unordered key-value map, intending to perfectly capture the semantics of a JSON object. This enables parsing any arbitrary JSON payload as a message field in ProtoJSON for… */
export interface Struct {
    /** Unordered map of dynamically typed values. */
    fields: { [key: string]: Value };
}

/** Represents a JSON value. `Value` represents a dynamically typed value which can be either null, a number, a string, a boolean, a recursive struct value, or a list of values. A producer of value is exp… */
export interface Value {
    /** The kind of value. */
    kind: {
        oneofKind: "nullValue";
        nullValue: NullValue;
    } | {
        oneofKind: "numberValue";
        numberValue: number;
    } | {
        oneofKind: "stringValue";
        stringValue: string;
    } | {
        oneofKind: "boolValue";
        boolValue: boolean;
    } | {
        oneofKind: "structValue";
        structValue: Struct;
    } | {
        oneofKind: "listValue";
        listValue: ListValue;
    } | {
        oneofKind: undefined;
    };
}

/** Represents a JSON array. */
export interface ListValue {
    /** Repeated field of dynamically typed values. */
    values: Value[];
}

/** Represents a JSON `null`. `NullValue` is a sentinel, using an enum with only one value to represent the null value for the `Value` type union. A field of type `NullValue` with any value other than `0`… */
export enum NullValue {
    NULL_VALUE = 0,
}

/** Wrapper message for `double`. The JSON representation for `DoubleValue` is JSON number. Not recommended for use in new APIs, but still useful for legacy APIs and has no plan to be removed. */
export interface DoubleValue {
    /** The double value. */
    value: number;
}

/** Wrapper message for `float`. The JSON representation for `FloatValue` is JSON number. Not recommended for use in new APIs, but still useful for legacy APIs and has no plan to be removed. */
export interface FloatValue {
    /** The float value. */
    value: number;
}

/** Wrapper message for `int64`. The JSON representation for `Int64Value` is JSON string. Not recommended for use in new APIs, but still useful for legacy APIs and has no plan to be removed. */
export interface Int64Value {
    /** The int64 value. */
    value: string;
}

/** Wrapper message for `uint64`. The JSON representation for `UInt64Value` is JSON string. Not recommended for use in new APIs, but still useful for legacy APIs and has no plan to be removed. */
