/** Wrapper message for `bytes`. The JSON representation for `BytesValue` is JSON string. Not recommended for use in new APIs, but still useful for legacy APIs and has no plan to be removed. */
export interface BytesValue {
    /** The bytes value. */
    value: Uint8Array;
}

/** Message containing all 15 proto3 scalar types */
export interface AllScalars {
    doubleField: number;
    floatField: number;
    int32Field: number;
    int64Field: string;
    uint32Field: number;
    uint64Field: string;
    sint32Field: number;
    sint64Field: string;
    fixed32Field: number;
    fixed64Field: string;
    sfixed32Field: number;
    sfixed64Field: string;
    boolField: boolean;
    stringField: string;
    bytesField: Uint8Array;
    /** Repeated bytes field */
    repeatedBytes: Uint8Array[];
}

/** Message containing all well-known types */
export interface AllWellKnownTypes {
    anyField?: Any;
    durationField?: Duration;
    emptyField?: Empty;
    maskField?: FieldMask;
    structField?: Struct;
    timestampField?: Timestamp;
    doubleValue?: DoubleValue;
    floatValue?: FloatValue;
    int64Value?: Int64Value;
    uint64Value?: UInt64Value;
    int32Value?: Int32Value;
    uint32Value?: UInt32Value;
    boolValue?: BoolValue;
    stringValue?: StringValue;
    bytesValue?: BytesValue;
}

/** Address with scalar types. Contains location data with latitude/longitude. Special chars in comment: <html> & "quotes" and backslash-n \n */
export interface Address {
    street: string;
    city: string;
    state: string;
    zipCode: string;
    country: string;
    /** trailing: latitude in degrees */
    latitude: number;
    /** trailing: longitude in degrees */
    longitude: number;
    isPrimary: boolean;
}

/** Metadata with various map key types */
export interface Metadata {
    labels: { [key: string]: string };
    counters: { [key: string]: number };
    flags: { [key: string]: boolean };
    indexedData: { [key: number]: string };
    /** Bool map key */
    boolMap: { [key: string]: string };
    /** Int64 map key */
    longMap: { [key: string]: string };
    /** Map with message values */
    priceMap: { [key: string]: Money };
}

/** Audit info with timestamps */
export interface AuditInfo {
    createdAt?: Timestamp;
    updatedAt?: Timestamp;
    createdBy: string;
    updatedBy: string;
    version: number;
}

/** Money representation */
export interface Money {
    currency: string;
    amountCents: string;
}

/** Pagination */
export interface PageInfo {
    page: number;
    pageSize: number;
    totalCount: number;
    hasNext: boolean;
    hasPrev: boolean;
}

/** Message with reserved field numbers and names */
export interface ReservedExample {
    activeField: string;
    currentField: string;
}

/** Deprecated: use FeatureFlags instead */
export interface LegacyConfig {
    key: string;
    value: string;
}

/** Message with deprecated fields */
export interface FeatureFlags {
    name: string;
    enabled: boolean;
    /** Deprecated: use enabled instead */
    active: boolean;
    description: string;
    /** Deprecated: use description instead */
    info: string;
}

/** Common status enum used across services */
export enum Status {
    UNSPECIFIED = 0,
    ACTIVE = 1,
    INACTIVE = 2,
    PENDING = 3,
    DELETED = 4,
}

/** Enum with deprecated values */
export enum Priority {
    UNSPECIFIED = 0,
    LOW = 1,
    MEDIUM = 2,
    HIGH = 3,
    CRITICAL = 4,
}

/** Enum with allow_alias - multiple names for the same value */
export enum Region {
    UNSPECIFIED = 0,
    US_EAST = 1,
    US_WEST = 2,
    EU = 3,
    EUROPE = 3,
    ASIA = 4,
    AP = 4,
}

/** Event with oneof payload including reserved name member */
export interface Event {
    id: string;
    userId: string;
    sessionId: string;
    type: EventType;
    timestamp?: Timestamp;
    payload: {
        oneofKind: "pageView";
        pageView: PageViewEvent;
    } | {
        oneofKind: "click";
        click: ClickEvent;
    } | {
        oneofKind: "search";
        search: SearchEvent;
    } | {
        oneofKind: "purchase";
        purchase: PurchaseEvent;
    } | {
        oneofKind: "constructor";
        constructor: number;
    } | {
        oneofKind: undefined;
    };
    properties: { [key: string]: string };
    metadata?: Metadata;
    /** Local status vs common.Status */
    analyticsStatus: Status;
}

export interface PageViewEvent {
    url: string;
    referrer: string;
    durationMs: number;
}

export interface ClickEvent {
    elementId: string;
    elementType: string;
    pageUrl: string;
}

export interface SearchEvent {
    query: string;
    resultsCount: number;
    filters: string[];
}

export interface PurchaseEvent {
    orderId: string;
    total?: Money;
    productIds: string[];
}

export interface TrackEventRequest {
    event?: Event;
}

export interface TrackEventResponse {
    success: boolean;
}

/** Streaming request for real-time event feed */
export interface StreamEventsRequest {
    userId: string;
    types: EventType[];
}

/** Request for batch event ingestion */
export interface BatchEvent {
    event?: Event;
    source: string;
}

/** Response for batch event ingestion */
export interface BatchEventResponse {
    processedCount: number;
    failedCount: number;
}

export interface GetEventsRequest {
    userId: string;
    type: EventType;
    startTime?: Timestamp;
    endTime?: Timestamp;
    page?: PageInfo;
}

export interface GetEventsResponse {
    events: Event[];
    page?: PageInfo;
}

/** Event type enum with reserved values */
export enum EventType {
    UNSPECIFIED = 0,
    PAGE_VIEW = 1,
    CLICK = 2,
    SEARCH = 3,
    PURCHASE = 4,
    ADD_TO_CART = 5,
}

/** Same-name type as common.Status to test cross-package name collision */
export enum Status {
    ANALYTICS_STATUS_UNSPECIFIED = 0,
    ANALYTICS_STATUS_PROCESSED = 1,
    ANALYTICS_STATUS_FAILED = 2,
}

/** Resource information for message-level option */
export interface ResourceInfo {
    type: string;
    pattern: string;
}

/** Nested permission message */
export interface Permission {
    resource: string;
    actions: string[];
    scope?: Permission_Scope;
}

export interface Permission_Scope {
    type: string;
    ids: string[];
}

/** User profile with nested messages */
export interface UserProfile {
    id: string;
    username: string;
    email: string;
    role: Role;
    address?: Address;
    permissions: Permission[];
    metadata?: Metadata;
    audit?: AuditInfo;
    preferences?: UserProfile_Preferences;
    /** Field with json_name */
    displayName: string;
    /** Reserved property name */
    Proto: boolean;
}

/** Nested preferences */
export interface UserProfile_Preferences {
    language: string;
    timezone: string;
    emailNotifications: boolean;
    smsNotifications: boolean;
}

/** Authentication request with oneof */
export interface AuthRequest {
    credentials: {
        oneofKind: "password";
        password: string;
    } | {
        oneofKind: "oauthToken";
        oauthToken: string;
    } | {
        oneofKind: "apiKey";
        apiKey: string;
    } | {
        oneofKind: undefined;
    };
    username: string;
    deviceId: string;
}

export interface AuthResponse {
    accessToken: string;
    refreshToken: string;
    profile?: UserProfile;
}

export interface CreateUserRequest {
    username: string;
    email: string;
    password: string;
    role: Role;
    address?: Address;
}

export interface CreateUserResponse {
    profile?: UserProfile;
}

export interface GetUserRequest {
    id: string;
}

export interface GetUserResponse {
    profile?: UserProfile;
}

/** Request for listing users with server streaming */
export interface ListUsersRequest {
    role: Role;
    page?: PageInfo;
}

/** Response for listing users */
export interface ListUsersResponse {
    profile?: UserProfile;
}

/** Request for bulk creating users with client streaming */
export interface BulkCreateUsersRequest {
    username: string;
    email: string;
    password: string;
    role: Role;
}

/** Response for bulk user creation */
export interface BulkCreateUsersResponse {
    createdCount: number;
    userIds: string[];
}

/** Chat message for bidirectional streaming */
export interface UserChatMessage {
    userId: string;
    content: string;
}

export interface UpdateUserRequest {
    id: string;
    profile?: UserProfile;
}

export interface UpdateUserResponse {
    profile?: UserProfile;
}

/** User role enum */
export enum Role {
    UNSPECIFIED = 0,
    CUSTOMER = 1,
    ADMIN = 2,
    SUPPORT = 3,
}

/** Message named WireType - collides with protobuf-ts runtime import */
export interface WireType {
    name: string;
    id: number;
}

/** Message named MessageType - collides with protobuf-ts runtime import */
export interface MessageType {
    name: string;
    description: string;
}

/** Same-name type as common.Metadata to test cross-package collision */
export interface Metadata {
    internalId: string;
    source: string;
}

/** Container with nested messages referencing collision types */
export interface Container {
    wire?: WireType;
    msg?: MessageType;
    meta?: Metadata;
    commonMeta?: Metadata$;
    inner?: Container_Inner;
}

export interface Container_Inner {
    value: string;
    wireRef?: WireType;
}

/** Product with nested variants */
export interface Product {
    id: string;
    name: string;
    description: string;
    category: Category;
    price?: Money;
    tags: string[];
    imageUrls: string[];
    status: Status;
    variants: Product_Variant[];
    metadata?: Metadata;
    audit?: AuditInfo;
    /** jstype JS_STRING on int64 field */
    viewCount: string;
    /** jstype JS_NUMBER on uint64 field */
    serialNumber: number;
    /** json_name with special characters */
    internalCode: string;
    /** TypeScript keywords as field names */
    const: string;
    class: string;
    typeof: string;
    delete: string;
}

/** Nested variant message (also see top-level Product_Variant) */
export interface Product_Variant {
    id: string;
    name: string;
    attributes: { [key: string]: string };
    price?: Money;
    stockQuantity: number;
    sku: string;
}

/** Top-level message that collides with Product.Variant in generated code */
export interface Product_Variant$1 {
    variantId: string;
    productId: string;
    label: string;
}

/** Review with nested rating breakdown */
export interface Review {
    id: string;
    productId: string;
    userId: string;
    rating: number;
    title: string;
    comment: string;
    imageUrls: string[];
    verifiedPurchase: boolean;
    helpfulCount: number;
    breakdown?: Review_RatingBreakdown;
    audit?: AuditInfo;
}

export interface Review_RatingBreakdown {
    quality: number;
    value: number;
    accuracy: number;
}

export interface CreateProductRequest {
    name: string;
    description: string;
    category: Category;
    price?: Money;
    tags: string[];
}

export interface CreateProductResponse {
    product?: Product;
}

export interface ListProductsRequest {
    category: Category;
    tags: string[];
    page?: PageInfo;
}

export interface ListProductsResponse {
    products: Product[];
    page?: PageInfo;
}

export interface GetProductRequest {
    id: string;
}

export interface GetProductResponse {
    product?: Product;
    reviews: Review[];
}

/** Product category enum */
export enum Category {
    UNSPECIFIED = 0,
    ELECTRONICS = 1,
    CLOTHING = 2,
    BOOKS = 3,
    HOME = 4,
    SPORTS = 5,
}

/** Order with 4-level deep nesting */
export interface Order {
    id: string;
    userId: string;
    status: OrderStatus;
    items: Order_LineItem[];
    subtotal?: Money;
    tax?: Money;
    shipping?: Money;
    total?: Money;
    shippingInfo?: Order_ShippingInfo;
    payment?: Order_PaymentInfo;
    audit?: AuditInfo;
    fulfillments: Order_Fulfillment[];
    /** Multiple oneofs in one message */
    paymentSource: {
        oneofKind: "creditCardId";
        creditCardId: string;
    } | {
        oneofKind: "bankAccountId";
        bankAccountId: string;
    } | {
        oneofKind: "walletId";
        walletId: string;
    } | {
        oneofKind: undefined;
    };
    discount: {
        oneofKind: "couponCode";
        couponCode: string;
    } | {
        oneofKind: "loyaltyPoints";
        loyaltyPoints: number;
    } | {
        oneofKind: "percentageOff";
        percentageOff: number;
    } | {
        oneofKind: undefined;
    };
    /** Proto3 optional fields */
    notes?: string;
    giftWrap?: boolean;
    priorityLevel?: number;
    /** Bool map key */
    flags: { [key: string]: string };
    /** Field named oneof_kind (discriminator collision) */
    oneofKind$: string;
}

export interface Order_LineItem {
    productId: string;
    variantId: string;
    quantity: number;
    unitPrice?: Money;
    totalPrice?: Money;
    product?: Product;
}

export interface Order_ShippingInfo {
    address?: Address;
    carrier: string;
    trackingNumber: string;
    estimatedDelivery?: Timestamp;
}

export interface Order_PaymentInfo {
    method: PaymentMethod;
    transactionId: string;
    amount?: Money;
    processedAt?: Timestamp;
}

/** 4-level deep nesting: Order > Fulfillment > Tracking > Checkpoint */
export interface Order_Fulfillment {
    fulfillmentId: string;
    items: Order_LineItem[];
    tracking?: Order_Fulfillment_Tracking;
    shippedAt?: Timestamp;
}

export interface Order_Fulfillment_Tracking {
    carrier: string;
    trackingNumber: string;
    checkpoints: Order_Fulfillment_Tracking_Checkpoint[];
    latest?: Order_Fulfillment_Tracking_Checkpoint;
}

export interface Order_Fulfillment_Tracking_Checkpoint {
    location: string;
    status: string;
    timestamp?: Timestamp;
    description: string;
}

/** Self-referential message */
export interface OrderGroup {
    id: string;
    name: string;
    children: OrderGroup[];
    orders: Order[];
}

export interface CreateOrderRequest {
    userId: string;
    items: CreateOrderRequest_Item[];
    shippingAddress?: Address;
    paymentMethod: PaymentMethod;
}

export interface CreateOrderRequest_Item {
    productId: string;
    variantId: string;
    quantity: number;
}

export interface CreateOrderResponse {
    order?: Order;
}

export interface GetOrderRequest {
    id: string;
}

export interface GetOrderResponse {
    order?: Order;
}

export interface UpdateOrderStatusRequest {
    id: string;
    status: OrderStatus;
}

export interface UpdateOrderStatusResponse {
    order?: Order;
}

/** Order status enum */
export enum OrderStatus {
    UNSPECIFIED = 0,
    PENDING = 1,
    CONFIRMED = 2,
    SHIPPED = 3,
    DELIVERED = 4,
    CANCELLED = 5,
    REFUNDED = 6,
}

/** Payment method with allow_alias */
export enum PaymentMethod {
    UNSPECIFIED = 0,
    CREDIT_CARD = 1,
    VISA = 1,
    DEBIT_CARD = 2,
    PAYPAL = 3,
    CRYPTO = 4,
    BITCOIN = 4,
}

/** Aggregated response combining data from multiple services */
export interface Dashboard {
    user?: UserProfile;
    featuredProducts: Product[];
    recentOrders: Order[];
    recentEvents: Event[];
    metadata?: Metadata;
    /** Circular self-reference via optional */
    parent?: Dashboard;
    /** Proto3 optional scalar fields */
    title?: string;
    refreshIntervalSeconds?: number;
    isPublic?: boolean;
    /** Reference to internal collision types */
    internalData?: Container;
}

/** Top-level message named Entry to coexist with map entry types */
export interface Entry {
    key: string;
    value: string;
}

/** Settings with a map field (generates SettingsEntry internally) */
export interface Settings {
    properties: { [key: string]: string };
    entries: { [key: string]: Entry };
}
